export type TaskOrchestratorGate = "Ready" | "Review" | "Blocked";
export type TaskLifecycleStatus = "done" | "active" | "queued" | "blocked";
export type TaskChecklistStatus = "pass" | "review" | "block";
export type TaskExecutionEventKind = "start" | "finish" | "review_gate" | "retry" | "skip";
export type TaskExecutionEventStatus = "done" | "running" | "review" | "blocked" | "queued";
export type TaskToolDcc = "Maya" | "Blender" | "3ds Max" | "Houdini" | "Figma" | "Substance" | "Engine" | "Platform";
export type TaskToolDomain =
  | "Asset Protocol"
  | "Validation"
  | "Visual Review"
  | "Texture Publish"
  | "Task Intake"
  | "Package Handoff"
  | "Platform Runtime";
export type TaskToolAvailability = "available" | "review_only" | "version_mismatch" | "missing";
export type TaskToolLaunchMode = "embedded_panel" | "dcc_adapter" | "headless_check" | "external_sync" | "dry_run";
export type TaskDiscoveryDiagnosticSeverity = "info" | "review" | "block";
export type TaskReviewerAcceptanceState = "accepted" | "pending" | "rejected" | "deferred";
export type TaskHandoffArtifactType = "report" | "manifest" | "receipt" | "packet" | "draft";
export type TaskPlatformReceiptState = "issued" | "held_for_review" | "blocked";
export type TaskImpactAssetKind = "source_mesh" | "material" | "texture_set" | "validation_rule" | "engine_package";
export type TaskImpactPublishAction = "safe_publish" | "hold" | "rerun_check" | "rollback_candidate";
export type TaskImpactReceiptState = "accepted" | "pending" | "waiting_dependency";

