export function getDefaultTaskOrchestratorReport(
  dependencyImpactScenarioId = DEFAULT_DEPENDENCY_IMPACT_SCENARIO_ID,
): TaskOrchestratorReport {
  const readinessChecklist = buildReadinessChecklist(taskLifecycle, taskModuleTraces);
  const gate = getTaskGate(readinessChecklist);
  const evidencePacket = buildEvidencePacket(taskModuleTraces);
  const executionEvents = buildExecutionEvents(taskModuleTraces);
  const executionSummary = buildExecutionSummary(executionEvents, taskModuleTraces);
  const dependencyGraph = buildDependencyGraph(taskModuleTraces, gate);
  const runDiff = buildRunDiff(previousRunSnapshot, taskModuleTraces);
  const assetDependencyImpact = buildAssetDependencyImpact(dependencyGraph, runDiff, dependencyImpactScenarioId);
  const toolDiscovery = buildToolDiscoveryReport(taskToolRegistry, gate);
  const reviewerAcceptance = buildReviewerAcceptanceReport(taskModuleTraces, toolDiscovery.launchManifest);
  const finalHandoffPacket = buildFinalHandoffPacket(evidencePacket, toolDiscovery.launchManifest, reviewerAcceptance);
  const platformReceipt = buildPlatformReceipt(finalHandoffPacket, reviewerAcceptance, toolDiscovery);

  return {
    reportVersion: "task-orchestrator-report@1.48.0",
    taskId: "portfolio-asset-delivery-001",
    title: "Portfolio Asset Delivery QC",
    gate,
    summary: buildTaskSummary(gate, taskModuleTraces),
    lifecycle: taskLifecycle,
    moduleTraces: taskModuleTraces,
    toolRegistry: taskToolRegistry,
    readinessChecklist,
    evidencePacket,
    executionSummary,
    executionEvents,
    dependencyGraph,
    runDiff,
    toolDiscovery,
    reviewerAcceptance,
    finalHandoffPacket,
    platformReceipt,
    assetDependencyImpact,
    aiHandoffDraft: buildAiHandoffDraft(
      gate,
      taskModuleTraces,
      readinessChecklist,
      evidencePacket,
      runDiff,
      toolDiscovery,
      reviewerAcceptance,
      finalHandoffPacket,
      platformReceipt,
      assetDependencyImpact,
    ),
  };
}

