function buildReviewerAcceptanceSummary(items: TaskReviewerAcceptanceItem[]): TaskReviewerAcceptanceSummary {
  const requiredPending = items.filter((item) => item.requiredForHandoff && item.state === "pending").length;
  const rejected = items.filter((item) => item.state === "rejected").length;
  const gate: TaskOrchestratorGate = rejected > 0 ? "Blocked" : requiredPending > 0 ? "Review" : "Ready";

  return {
    gate,
    total: items.length,
    accepted: items.filter((item) => item.state === "accepted").length,
    pending: items.filter((item) => item.state === "pending").length,
    rejected,
    deferred: items.filter((item) => item.state === "deferred").length,
    requiredPending,
    nextAction: requiredPending > 0
      ? "Resolve R2 adapter acceptance and R4 approved-package delta before issuing platform receipt."
      : "All required reviewer receipts are accepted; package can move to platform receipt.",
  };
}

function buildFinalHandoffPacket(
  evidencePacket: TaskEvidencePacket,
  launchManifest: TaskLaunchManifest,
  reviewerAcceptance: TaskReviewerAcceptanceReport,
): TaskFinalHandoffPacket {
  const artifacts: TaskHandoffArtifact[] = [
    {
      id: "artifact-evidence-packet",
      label: "Aggregated Evidence Packet",
      type: "packet",
      path: evidencePacket.packetId,
      required: true,
      gate: "Ready",
    },
    {
      id: "artifact-launch-manifest",
      label: "Dry-run Launch Manifest",
      type: "manifest",
      path: launchManifest.manifestId,
      required: true,
      gate: launchManifest.gate,
    },
    {
      id: "artifact-r2-report",
      label: "Cross-DCC Rule Matrix Report",
      type: "report",
      path: "assets/cross-dcc-rule-matrix-r2-3-exported-report.json",
      required: true,
      gate: "Review",
    },
    {
      id: "artifact-r4-report",
      label: "Texture Delivery Adapter Report",
      type: "report",
      path: "assets/texture-delivery-r4-6-exported-report.json",
      required: true,
      gate: "Review",
    },
    {
      id: "artifact-ai-handoff",
      label: "AI Handoff Draft",
      type: "draft",
      path: "report.aiHandoffDraft",
      required: false,
      gate: "Ready",
    },
  ];
  const blockedReasons = reviewerAcceptance.items
    .filter((item) => item.requiredForHandoff && item.state !== "accepted")
    .map((item) => `${item.owner}: ${item.scope} is ${item.state}.`);
  const requiredAccepted = blockedReasons.length === 0;
  const gate: TaskOrchestratorGate = reviewerAcceptance.summary.gate === "Blocked"
    ? "Blocked"
    : requiredAccepted && launchManifest.gate === "Ready"
      ? "Ready"
      : "Review";
  const reviewReceiptIds = reviewerAcceptance.items.map((item) => item.receiptId);
  const packetHash = stableTaskId(
    "handoff",
    `${evidencePacket.packetHash}|${launchManifest.manifestId}|${reviewReceiptIds.join("|")}|${gate}`,
  );

  return {
    packetId: "final_handoff_portfolio_asset_delivery_001",
    gate,
    readyForPlatform: gate === "Ready",
    artifactCount: artifacts.length,
    requiredAccepted,
    launchManifestId: launchManifest.manifestId,
    evidencePacketId: evidencePacket.packetId,
    reviewReceiptIds,
    artifacts,
    blockedReasons,
    packetHash,
    summary: requiredAccepted
      ? "Required reviewer receipts are accepted. Final packet can request platform receipt."
      : `${blockedReasons.length} required reviewer acceptance item(s) remain before platform receipt.`,
  };
}

function buildPlatformReceipt(
  finalHandoffPacket: TaskFinalHandoffPacket,
  reviewerAcceptance: TaskReviewerAcceptanceReport,
  toolDiscovery: TaskToolDiscoveryReport,
): TaskPlatformReceipt {
  const issued = finalHandoffPacket.readyForPlatform && toolDiscovery.launchManifest.entries.every((entry) => !entry.mutationAllowed);
  const conditions = [
    reviewerAcceptance.summary.requiredPending === 0
      ? "All required owner acceptances are recorded."
      : `${reviewerAcceptance.summary.requiredPending} required owner acceptance item(s) remain pending.`,
    toolDiscovery.launchManifest.entries.every((entry) => entry.dryRun && !entry.mutationAllowed)
      ? "All launch manifest entries are dry-run and mutationAllowed=false."
      : "Launch manifest contains a mutating entry.",
    toolDiscovery.summary.missingTools > 0
      ? "Missing optional external sync is deferred to manual export."
      : "No missing tool diagnostics remain.",
    finalHandoffPacket.readyForPlatform
      ? "Final handoff packet gate is Ready."
      : `Final handoff packet gate is ${finalHandoffPacket.gate}.`,
  ];
  const state: TaskPlatformReceiptState = issued ? "issued" : finalHandoffPacket.gate === "Blocked" ? "blocked" : "held_for_review";
  const checksum = stableTaskId("platform", `${finalHandoffPacket.packetHash}|${state}|${conditions.join("|")}`);

  return {
    receiptId: stableTaskId("receipt", `${finalHandoffPacket.packetId}|${state}`),
    state,
    gate: finalHandoffPacket.gate,
    issued,
    recipient: "Build Pipeline",
    createdAt: "2026-07-30T21:05:00+08:00",
    handoffPacketId: finalHandoffPacket.packetId,
    checksum,
    conditions,
  };
}

export function filterDiscoveredTools(
  tools: TaskToolRegistryEntry[],
  filters: TaskToolDiscoveryFilters,
): TaskToolRegistryEntry[] {
  return tools.filter((tool) => {
    const dccMatches = filters.dcc === "all" || tool.dccTargets.includes(filters.dcc);
    const domainMatches = filters.domain === "all" || tool.domains.includes(filters.domain);
    const ownerMatches = filters.owner === "all" || tool.owner === filters.owner;
    const inputMatches = filters.inputContract === "all" || tool.inputContract === filters.inputContract;
    return dccMatches && domainMatches && ownerMatches && inputMatches;
  });
}

function buildToolDiscoveryReport(
  tools: TaskToolRegistryEntry[],
  taskGate: TaskOrchestratorGate,
): TaskToolDiscoveryReport {
  const diagnostics = buildDiscoveryDiagnostics(tools);
  const launchManifest = buildLaunchManifest(tools, taskGate, diagnostics);
  const missingRequired = tools.some((tool) => tool.requiredForHandoff && tool.availability === "missing");
  const reviewRequired = tools.some((tool) => tool.availability !== "available") || taskGate === "Review";
  const summaryGate: TaskOrchestratorGate = missingRequired ? "Blocked" : reviewRequired ? "Review" : "Ready";

  return {
    summary: {
      gate: summaryGate,
      totalTools: tools.length,
      availableTools: tools.filter((tool) => tool.availability === "available").length,
      reviewOnlyTools: tools.filter((tool) => tool.availability === "review_only").length,
      versionMismatches: tools.filter((tool) => tool.availability === "version_mismatch").length,
      missingTools: tools.filter((tool) => tool.availability === "missing").length,
      launchableTools: tools.filter((tool) => tool.availability !== "missing").length,
      nextAction: "Use available tools inside portfolio, keep Figma intake and asset platform sync as dry-run launch intents, and wait for owner review before handoff.",
    },
    filterOptions: buildDiscoveryFilterOptions(tools),
    defaultFilters: {
      dcc: "all",
      domain: "all",
      owner: "all",
      inputContract: "all",
    },
    diagnostics,
    launchManifest,
  };
}

function buildDiscoveryFilterOptions(tools: TaskToolRegistryEntry[]): TaskToolDiscoveryFilterOptions {
  return {
    dcc: ["all", ...uniqueSorted(tools.flatMap((tool) => tool.dccTargets))],
    domains: ["all", ...uniqueSorted(tools.flatMap((tool) => tool.domains))],
    owners: ["all", ...uniqueSorted(tools.map((tool) => tool.owner))],
    inputContracts: ["all", ...uniqueSorted(tools.map((tool) => tool.inputContract))],
  };
}

function buildDiscoveryDiagnostics(tools: TaskToolRegistryEntry[]): TaskDiscoveryDiagnostic[] {
  const diagnostics: TaskDiscoveryDiagnostic[] = [];

  tools.forEach((tool) => {
    if (tool.availability === "available") {
      diagnostics.push({
        id: `diag-${tool.id}-available`,
        toolId: tool.id,
        severity: "info",
        title: `${tool.label} is discoverable`,
        detail: `${tool.detectedVersion} satisfies ${tool.minVersion}; launch mode is ${tool.launchMode}.`,
        action: "Keep telemetry and output contract attached to the launch manifest.",
      });
      return;
    }
    if (tool.availability === "review_only") {
      diagnostics.push({
        id: `diag-${tool.id}-review`,
        toolId: tool.id,
        severity: "review",
        title: `${tool.label} is review-only`,
        detail: "The tool can produce a launch plan, but owner acceptance is still required before package handoff.",
        action: "Record dry-run receipt and attach it to the review packet.",
      });
      return;
    }
    if (tool.availability === "version_mismatch") {
      diagnostics.push({
        id: `diag-${tool.id}-version`,
        toolId: tool.id,
        severity: "review",
        title: `${tool.label} version mismatch`,
        detail: `Detected ${tool.detectedVersion ?? "none"}, required ${tool.minVersion}.`,
        action: "Keep the launch entry disabled for mutation and request adapter upgrade or compatibility approval.",
      });
      return;
    }
    diagnostics.push({
      id: `diag-${tool.id}-missing`,
      toolId: tool.id,
      severity: tool.requiredForHandoff ? "block" : "review",
      title: `${tool.label} is missing`,
      detail: "No local adapter version was detected for this optional external sync path.",
      action: "Export the evidence packet locally and keep the external sync as a recorded intent.",
    });
  });

  return diagnostics;
}

function buildLaunchManifest(
  tools: TaskToolRegistryEntry[],
  taskGate: TaskOrchestratorGate,
  diagnostics: TaskDiscoveryDiagnostic[],
): TaskLaunchManifest {
  const entries = tools.map((tool) => {
    const gate = getLaunchGate(tool, taskGate);
    const args = buildLaunchArgs(tool);
    const command = tool.commandTemplate.split(" ")[0];
    const diagnostic = diagnostics.find((item) => item.toolId === tool.id);
    return {
      id: `launch-${tool.id}`,
      toolId: tool.id,
      label: tool.label,
      gate,
      launchMode: tool.launchMode,
      command,
      args,
      env: {
        TASK_ID: "portfolio-asset-delivery-001",
        TOOL_ID: tool.id,
        LAUNCH_MODE: tool.launchMode,
      },
      dryRun: true,
      mutationAllowed: false,
      reason: diagnostic?.action ?? "Launch recorded as a non-mutating portfolio dry-run.",
      telemetryEvent: tool.telemetryEvent,
      receiptId: stableTaskId("launch", `${tool.id}|${tool.detectedVersion ?? "missing"}|${gate}`),
    };
  });

  return {
    manifestId: stableTaskId("launch_manifest", entries.map((entry) => entry.receiptId).join("|")),
    gate: entries.some((entry) => entry.gate === "Blocked") ? "Review" : taskGate,
    dryRun: true,
    entries,
    boundaryRules: [
      "Discovery can rank and filter tools, but it cannot invent a missing adapter.",
      "Launch manifest records command intent, environment contract, telemetry event, and receipt id.",
      "Every portfolio launch entry is dry-run and mutationAllowed=false.",
      "External Figma, asset platform, DCC, compressor, and engine sessions are represented as mocked adapter boundaries.",
    ],
  };
}

function getLaunchGate(tool: TaskToolRegistryEntry, taskGate: TaskOrchestratorGate): TaskOrchestratorGate {
  if (tool.availability === "missing") {
    return "Blocked";
  }
  if (tool.availability === "version_mismatch" || tool.availability === "review_only" || taskGate !== "Ready") {
    return "Review";
  }
  return "Ready";
}

function buildLaunchArgs(tool: TaskToolRegistryEntry): string[] {
  return tool.commandTemplate
    .split(" ")
    .slice(1)
    .map((arg) =>
      arg
        .replace("{taskId}", "portfolio-asset-delivery-001")
        .replace("{assetFixture}", "synthetic-rifle-a")
        .replace("{dcc}", tool.dccTargets[0])
        .replace("{platformPreset}", "ue_orm_bc")
        .replace("{frozenManifest}", "WPN_Rifle_A_Body_pc_dx12_txpkg_1lc6vtr")
        .replace("{packetId}", "packet_portfolio_asset_delivery_001"),
    );
}

