function buildProductionHandoffDiff(
  adapterContractReplay: TaskImpactAdapterContractReplay,
  externalReceiptSyncMock: TaskImpactExternalReceiptSyncMock,
  replayFailureRecovery: TaskImpactReplayFailureRecovery,
): TaskImpactProductionHandoffDiff {
  const rows: TaskImpactProductionHandoffDiffRow[] = externalReceiptSyncMock.payloads.map((payload) => {
    const recoveryIncident = replayFailureRecovery.incidents.find(
      (incident) => incident.sourceVariantId === payload.sourceVariantId,
    );
    const isReady = payload.syncAction === "create_draft";
    const isBlocked = payload.syncAction === "skip_blocked";
    return {
      id: stableTaskId("handoffrow", `${payload.payloadId}|${payload.syncAction}|${payload.owner}`),
      sourceVariantId: payload.sourceVariantId,
      targetSystem: payload.targetSystem,
      owner: payload.owner,
      field: isReady ? "receiptDraft.status" : isBlocked ? "releaseQueue.state" : "taskReceipt.comment",
      before: isReady ? "none" : "mock payload only",
      after: isReady ? "draft_ready" : isBlocked ? "skip_blocked_until_owner_fix" : "held_for_adapter_owner_review",
      status: isReady ? "added" : isBlocked ? "held" : "changed",
      gate: isReady ? "Ready" : "Review",
      reviewerNote: recoveryIncident
        ? `${payload.owner} must review ${recoveryIncident.failureMode} before production handoff.`
        : "Draft handoff can be generated after adapter owner approval.",
    };
  });
  const reviewRows = rows.filter((row) => row.gate === "Review").length;

  return {
    reportVersion: "impact-production-handoff-diff@0.1.0",
    diffId: stableTaskId("handoffdiff", `${adapterContractReplay.contractId}|${externalReceiptSyncMock.syncId}|${rows.map((row) => row.id).join("|")}`),
    mode: "production_handoff_diff",
    generatedAt: "2026-07-30T23:59:59+08:00",
    baselinePacketId: adapterContractReplay.contractId,
    candidatePacketId: externalReceiptSyncMock.syncId,
    gate: reviewRows > 0 ? "Review" : "Ready",
    summary: {
      totalRows: rows.length,
      readyRows: rows.filter((row) => row.gate === "Ready").length,
      reviewRows,
      blockedRows: rows.filter((row) => row.status === "held").length,
      changedFields: rows.filter((row) => row.status !== "unchanged").length,
      gate: reviewRows > 0 ? "Review" : "Ready",
      nextAction: "Review changed and held handoff rows with the adapter owner before enabling any production receipt write.",
    },
    rows,
    signoffRequired: ["Platform Adapter Owner", "Release TA", "Texture TA"],
    artifacts: [
      "fixtures/dependency-impact/r8-7-production-handoff.json",
      "assets/task-orchestrator-r8-7-exported-report.json",
    ],
  };
}

