function buildHeldPayloadRetryLedger(
  externalReceiptSyncMock: TaskImpactExternalReceiptSyncMock,
  replayFailureRecovery: TaskImpactReplayFailureRecovery,
  adapterOwnerApprovalPacket: TaskImpactAdapterOwnerApprovalPacket,
): TaskImpactHeldPayloadRetryLedger {
  const heldPayloads = externalReceiptSyncMock.payloads.filter((payload) => payload.syncAction !== "create_draft");
  const entries: TaskImpactHeldPayloadRetryEntry[] = heldPayloads.map((payload, index) => {
    const incident = replayFailureRecovery.incidents.find((candidate) => candidate.sourceVariantId === payload.sourceVariantId);
    const isBlocked = payload.syncAction === "skip_blocked";
    const state = isBlocked ? "blocked" : index === 0 ? "waiting_owner" : "retry_ready";
    const requiredApprovalIds =
      state === "retry_ready"
        ? ["approval-endpoint-owner"]
        : state === "waiting_owner"
          ? ["approval-endpoint-owner", "approval-handoff-diff-reviewed"]
          : ["approval-blocked-skip-policy", "approval-credential-scope"];

    return {
      id: stableTaskId("retryentry", `${payload.payloadId}|${state}|${index + 1}`),
      payloadId: payload.payloadId,
      sourceVariantId: payload.sourceVariantId,
      owner: payload.owner,
      attempt: index + 1,
      state,
      lastFailureMode: incident?.failureMode ?? "held_payload",
      retryCommand:
        incident?.retryCommand ??
        `impact-contract-replay --variant ${payload.sourceVariantId} --approval ${adapterOwnerApprovalPacket.packetId} --dry-run --no-write`,
      requiredApprovalIds,
      nextCheck:
        state === "retry_ready"
          ? "Replay adapter-only after endpoint owner confirms contract."
          : state === "waiting_owner"
            ? "Wait for owner approval packet before retry."
            : "Do not retry until the blocked variant fixture changes.",
      evidence: [payload.payloadId, adapterOwnerApprovalPacket.packetId, ...(incident ? incident.evidence : [])],
    };
  });

  return {
    reportVersion: "impact-held-payload-retry-ledger@0.1.0",
    ledgerId: stableTaskId("retryledger", entries.map((entry) => `${entry.id}|${entry.state}`).join("|")),
    generatedAt: "2026-07-30T23:59:59+08:00",
    gate: entries.some((entry) => entry.state === "blocked") ? "Review" : "Ready",
    summary: {
      totalEntries: entries.length,
      retryReady: entries.filter((entry) => entry.state === "retry_ready").length,
      waitingOwner: entries.filter((entry) => entry.state === "waiting_owner").length,
      blocked: entries.filter((entry) => entry.state === "blocked").length,
      gate: entries.some((entry) => entry.state === "blocked") ? "Review" : "Ready",
      nextAction: "Retry only payloads marked retry_ready after adapter owner approval; blocked payloads require fixture repair first.",
    },
    entries,
    artifacts: [
      "fixtures/dependency-impact/r8-7-production-handoff.json",
      "assets/task-orchestrator-r8-7-exported-report.json",
    ],
  };
}

