function buildRollbackReceiptVerification(
  signedReceiptSandbox: TaskImpactSignedReceiptSandbox,
  productionAdapterSmokeHarness: TaskImpactProductionAdapterSmokeHarness,
  heldPayloadRetryLedger: TaskImpactHeldPayloadRetryLedger,
): TaskImpactRollbackReceiptVerification {
  const signedBoundary = signedReceiptSandbox.receipts.find((receipt) => receipt.scope === "no-write receipt boundary");
  const retryReadyEntry = heldPayloadRetryLedger.entries.find((entry) => entry.state === "retry_ready");
  const waitingOwnerEntry = heldPayloadRetryLedger.entries.find((entry) => entry.state === "waiting_owner");
  const heldRollback = signedReceiptSandbox.receipts.find((receipt) => receipt.scope === "blocked payload rollback hold");
  const entries: TaskImpactRollbackReceiptVerificationEntry[] = [
    {
      id: "rollback-no-write-boundary",
      sourceReceiptId: signedBoundary?.id ?? signedReceiptSandbox.sandboxId,
      rollbackReceiptId: stableTaskId("rollback", `${signedBoundary?.id ?? signedReceiptSandbox.sandboxId}|no-write`),
      owner: "Platform Adapter Owner",
      state: "verified",
      gate: "Ready",
      trigger: "smoke harness detects production write disabled",
      restorationTarget: "receipt-sync queue remains unchanged",
      proof: "writeAttempts stayed at zero and sandbox signature is replayable.",
      nextAction: "Keep this rollback receipt as the baseline for live adapter smoke.",
      evidence: [productionAdapterSmokeHarness.harnessId, signedBoundary?.signatureHash ?? signedReceiptSandbox.sandboxId],
    },
    {
      id: "rollback-retry-ready-payload",
      sourceReceiptId: retryReadyEntry?.id ?? heldPayloadRetryLedger.ledgerId,
      rollbackReceiptId: stableTaskId("rollback", `${retryReadyEntry?.id ?? heldPayloadRetryLedger.ledgerId}|retry-ready`),
      owner: retryReadyEntry?.owner ?? "Platform Adapter Owner",
      state: "verified",
      gate: "Ready",
      trigger: "retry-ready replay fails before external write",
      restorationTarget: "held payload returns to retry ledger with same attempt count",
      proof: "retry_ready entry is linked to a replayable sandbox signature.",
      nextAction: "Use this as the expected rollback path for transient adapter failure.",
      evidence: retryReadyEntry ? [retryReadyEntry.id, ...retryReadyEntry.evidence] : [heldPayloadRetryLedger.ledgerId],
    },
    {
      id: "rollback-waiting-owner-payload",
      sourceReceiptId: waitingOwnerEntry?.id ?? heldRollback?.id ?? heldPayloadRetryLedger.ledgerId,
      rollbackReceiptId: stableTaskId("rollback", `${waitingOwnerEntry?.id ?? heldPayloadRetryLedger.ledgerId}|waiting-owner`),
      owner: waitingOwnerEntry?.owner ?? "Release TA",
      state: "waiting_owner",
      gate: "Review",
      trigger: "owner approval is still requested",
      restorationTarget: "payload remains held_for_review and cannot advance",
      proof: "waiting_owner payload lacks the signed approval needed for replay.",
      nextAction: "Collect owner approval before promoting this rollback receipt to verified.",
      evidence: waitingOwnerEntry ? [waitingOwnerEntry.id, ...waitingOwnerEntry.evidence] : [heldPayloadRetryLedger.ledgerId],
    },
  ];
  const waitingOwner = entries.filter((entry) => entry.state === "waiting_owner").length;
  const blockedRollbacks = entries.filter((entry) => entry.state === "blocked").length;
  const gate: TaskOrchestratorGate = blockedRollbacks > 0 ? "Blocked" : waitingOwner > 0 ? "Review" : "Ready";

  return {
    reportVersion: "impact-rollback-receipt-verification@0.1.0",
    verificationId: stableTaskId("rollbackverify", entries.map((entry) => `${entry.id}|${entry.state}`).join("|")),
    mode: "rollback_receipt_verification",
    generatedAt: "2026-07-30T23:59:59+08:00",
    gate,
    summary: {
      totalRollbacks: entries.length,
      verifiedRollbacks: entries.filter((entry) => entry.state === "verified").length,
      waitingOwner,
      blockedRollbacks,
      gate,
      nextAction: "Promote waiting-owner rollback only after the approval packet is signed; blocked payloads stay outside retry.",
    },
    entries,
    guardrails: [
      "Rollback receipts restore queue state, not asset files.",
      "Rollback verification never upgrades a held payload to signed by itself.",
      "Blocked payloads require fixture repair before a rollback receipt can become replayable.",
    ],
    artifacts: [
      "fixtures/dependency-impact/r8-8-signed-receipt-sandbox.json",
      "assets/task-orchestrator-r8-8-exported-report.json",
    ],
  };
}

