function buildDrillbookAcceptanceLedger(
  ownerReopenIncidentDrillbook: TaskImpactOwnerReopenIncidentDrillbook,
  restorationDrillAcceptanceLedger: TaskImpactRestorationDrillAcceptanceLedger,
): TaskImpactDrillbookAcceptanceLedger {
  const acceptedDrills = restorationDrillAcceptanceLedger.rows.filter((row) => row.state === "drill_accepted");
  const reviewDrills = restorationDrillAcceptanceLedger.rows.filter((row) => row.state === "acceptance_review");
  const ownerHeldDrills = restorationDrillAcceptanceLedger.rows.filter((row) => row.state === "owner_hold" || row.state === "blocked");
  const rows: TaskImpactDrillbookAcceptanceLedgerRow[] = ownerReopenIncidentDrillbook.rows.map((row, index) => {
    const indexedAcceptance = restorationDrillAcceptanceLedger.rows[index] ?? restorationDrillAcceptanceLedger.rows[0];
    const acceptance =
      row.state === "drillbook_ready"
        ? acceptedDrills[index % acceptedDrills.length] ?? indexedAcceptance
        : row.state === "drillbook_review"
          ? reviewDrills[index % reviewDrills.length] ?? indexedAcceptance
          : ownerHeldDrills[index % ownerHeldDrills.length] ?? indexedAcceptance;
    if (row.state === "drillbook_ready" && acceptance?.state === "drill_accepted") {
      return {
        id: `drillbook-acceptance-ledger-${row.id}`,
        label: `${row.drillLane} drillbook accepted`,
        state: "drillbook_accepted",
        gate: "Ready",
        sourceIncidentDrillbookRowId: row.id,
        sourceAcceptanceRowId: acceptance.id,
        owner: row.owner,
        acceptanceLane: row.drillLane,
        acceptanceRef: `accepted-${row.drillRef}`,
        acceptanceScope: row.incidentScenario,
        acceptanceRule: "ready owner reopen drillbook and accepted restoration drill evidence can enter public acceptance ledger",
        acceptanceResult: "drillbook acceptance is recorded as public rehearsal evidence",
        acceptanceEffect: "lane proves duplicate-reopen handling without creating owner acceptance, opening incidents, paging owners, or executing restore",
        liveWrites: 0,
        privateFieldsExposed: 0,
        evidence: [
          row.id,
          acceptance.id,
          ownerReopenIncidentDrillbook.drillbookId,
          restorationDrillAcceptanceLedger.ledgerId,
          "fixtures/dependency-impact/r8-54-drillbook-acceptance-ledger.json",
          "assets/task-orchestrator-r8-54-exported-report.json",
        ],
        nextAction: "Publish accepted drillbook lane as final public duplicate-reopen rehearsal evidence.",
      };
    }
    if (row.state === "drillbook_review" || acceptance?.state === "acceptance_review") {
      return {
        id: `drillbook-acceptance-ledger-${row.id}`,
        label: `${row.drillLane} drillbook acceptance review`,
        state: "acceptance_review",
        gate: "Review",
        sourceIncidentDrillbookRowId: row.id,
        sourceAcceptanceRowId: acceptance?.id ?? restorationDrillAcceptanceLedger.ledgerId,
        owner: row.owner,
        acceptanceLane: row.drillLane,
        acceptanceRef: `review-${row.drillRef}`,
        acceptanceScope: row.incidentScenario,
        acceptanceRule: "drillbook-review or acceptance-review rows cannot be accepted from public data",
        acceptanceResult: "drillbook acceptance remains under public review",
        acceptanceEffect: "lane cannot create acceptance, open incidents, page owners, execute restore, or mutate archive systems",
        liveWrites: 0,
        privateFieldsExposed: 0,
        evidence: [
          row.id,
          acceptance?.id ?? restorationDrillAcceptanceLedger.ledgerId,
          ownerReopenIncidentDrillbook.drillbookId,
          restorationDrillAcceptanceLedger.ledgerId,
          "fixtures/dependency-impact/r8-54-drillbook-acceptance-ledger.json",
          "assets/task-orchestrator-r8-54-exported-report.json",
        ],
        nextAction: "Resolve incident drillbook or restoration acceptance review before acceptance ledger closeout.",
      };
    }
    return {
      id: `drillbook-acceptance-ledger-${row.id}`,
      label: `${row.drillLane} drillbook acceptance owner-held`,
      state: row.state === "blocked" || acceptance?.state === "blocked" ? "blocked" : "owner_hold",
      gate: row.state === "blocked" || acceptance?.state === "blocked" ? "Blocked" : "Review",
      sourceIncidentDrillbookRowId: row.id,
      sourceAcceptanceRowId: acceptance?.id ?? restorationDrillAcceptanceLedger.ledgerId,
      owner: "Owner Required",
      acceptanceLane: row.drillLane,
      acceptanceRef: `owner-held-${row.drillRef}`,
      acceptanceScope: "owner-redacted",
      acceptanceRule: "owner-held drillbook or drill acceptance cannot be accepted from public package data",
      acceptanceResult: "drillbook acceptance remains owner-held and redacted",
      acceptanceEffect: "lane cannot create owner acceptance, open incidents, page owners, execute restore, override holds, or mutate archive systems",
      liveWrites: 0,
      privateFieldsExposed: 0,
      evidence: [
        row.id,
        acceptance?.id ?? restorationDrillAcceptanceLedger.ledgerId,
        ownerReopenIncidentDrillbook.drillbookId,
        restorationDrillAcceptanceLedger.ledgerId,
        "fixtures/dependency-impact/r8-54-drillbook-acceptance-ledger.json",
        "assets/task-orchestrator-r8-54-exported-report.json",
      ],
      nextAction: "Keep owner-held drillbook acceptance redacted until owner evidence arrives outside the package.",
    };
  });
  const reviewRows = rows.filter((row) => row.state === "acceptance_review").length;
  const ownerHoldRows = rows.filter((row) => row.state === "owner_hold").length;
  const blockedRows = rows.filter((row) => row.state === "blocked").length;
  const gate: TaskOrchestratorGate = blockedRows > 0 ? "Blocked" : reviewRows + ownerHoldRows > 0 ? "Review" : "Ready";

  return {
    reportVersion: "impact-drillbook-acceptance-ledger@0.1.0",
    ledgerId: stableTaskId("drillbookacceptance", rows.map((row) => `${row.id}|${row.state}|${row.acceptanceRef}`).join("|")),
    mode: "drillbook_acceptance_ledger",
    generatedAt: "2026-07-31T23:59:59+08:00",
    mutationAllowed: false,
    privateDataExposed: false,
    gate,
    summary: {
      totalRows: rows.length,
      acceptedRows: rows.filter((row) => row.state === "drillbook_accepted").length,
      reviewRows,
      ownerHoldRows,
      blockedRows,
      liveWrites: rows.reduce((sum, row) => sum + row.liveWrites, 0),
      privateFieldsExposed: 0,
      gate,
      nextAction: "Record only accepted public drillbooks; review and owner-held lanes cannot create acceptance or incident actions.",
    },
    rows,
    guardrails: [
      "Drillbook acceptance ledger cannot create owner acceptance or open incidents.",
      "Accepted rows require ready reopen drillbook and accepted restoration drill evidence.",
      "Owner-held acceptance rows stay redacted and cannot page owners, execute restore, or mutate archive state.",
    ],
    artifacts: [
      "fixtures/dependency-impact/r8-54-drillbook-acceptance-ledger.json",
      "assets/task-orchestrator-r8-54-exported-report.json",
    ],
  };
}

