function buildReadinessChecklist(
  lifecycle: TaskLifecycleStep[],
  traces: TaskModuleTrace[],
): TaskReadinessItem[] {
  const activeSteps = lifecycle.filter((step) => step.status === "active");
  const reviewTraces = traces.filter((trace) => trace.gate === "Review");
  const blockedTraces = traces.filter((trace) => trace.gate === "Blocked");
  const totalEvidence = traces.reduce((sum, trace) => sum + trace.evidenceCount, 0);

  return [
    {
      id: "scope_ready",
      label: "Task scope",
      status: "pass",
      detail: "Task has lifecycle, module routing, owners, entry criteria, and exit evidence.",
    },
    {
      id: "module_trace",
      label: "Module trace",
      status: blockedTraces.length > 0 ? "block" : reviewTraces.length > 0 ? "review" : "pass",
      detail: `${traces.length} module trace(s), ${reviewTraces.length} review gate(s), ${blockedTraces.length} blocker(s).`,
    },
    {
      id: "active_work",
      label: "Active work",
      status: activeSteps.length > 0 ? "review" : "pass",
      detail: activeSteps.length > 0 ? `${activeSteps.map((step) => step.label).join(", ")} still active.` : "No active lifecycle steps.",
    },
    {
      id: "evidence_packet",
      label: "Evidence packet",
      status: totalEvidence >= 20 ? "pass" : "review",
      detail: `${totalEvidence} evidence item(s) referenced across R1-R4.`,
    },
    {
      id: "tool_registry",
      label: "Tool registry",
      status: taskToolRegistry.length >= traces.length ? "pass" : "review",
      detail: `${taskToolRegistry.length} registered tool entry(s) with input and output contracts.`,
    },
  ];
}

function getTaskGate(checklist: TaskReadinessItem[]): TaskOrchestratorGate {
  if (checklist.some((item) => item.status === "block")) {
    return "Blocked";
  }
  if (checklist.some((item) => item.status === "review")) {
    return "Review";
  }
  return "Ready";
}

function buildEvidencePacket(traces: TaskModuleTrace[]): TaskEvidencePacket {
  const artifacts = traces.map((trace) => trace.reportArtifact);
  return {
    packetId: "packet_portfolio_asset_delivery_001",
    itemCount: traces.reduce((sum, trace) => sum + trace.evidenceCount, 0),
    artifacts,
    packetHash: stableTaskId("taskpkg", artifacts.join("|")),
  };
}

function buildTaskSummary(gate: TaskOrchestratorGate, traces: TaskModuleTrace[]): string {
  const reviewModules = traces.filter((trace) => trace.gate === "Review").map((trace) => trace.moduleName);
  if (gate === "Blocked") {
    return "Task package has blocking module traces and cannot move to handoff.";
  }
  if (gate === "Review") {
    return `${reviewModules.join(", ")} require owner review before package handoff.`;
  }
  return "All module traces are ready for package handoff.";
}

function buildAiHandoffDraft(
  gate: TaskOrchestratorGate,
  traces: TaskModuleTrace[],
  checklist: TaskReadinessItem[],
  evidencePacket: TaskEvidencePacket,
  runDiff: TaskRunDiff,
  toolDiscovery: TaskToolDiscoveryReport,
  reviewerAcceptance: TaskReviewerAcceptanceReport,
  finalHandoffPacket: TaskFinalHandoffPacket,
  platformReceipt: TaskPlatformReceipt,
  assetDependencyImpact: TaskAssetDependencyImpact,
): string {
  const reviewItems = checklist.filter((item) => item.status !== "pass").map((item) => item.label);
  const blockers = traces.filter((trace) => trace.publishBlocker !== "none").map((trace) => `${trace.phase}:${trace.publishBlocker}`);
  return [
    `[Task Orchestrator] Portfolio Asset Delivery QC`,
    `Gate: ${gate}`,
    `Evidence packet: ${evidencePacket.packetId} (${evidencePacket.itemCount} items, ${evidencePacket.packetHash})`,
    `Run diff: ${runDiff.changedModules} changed module(s), ${runDiff.evidenceDelta > 0 ? "+" : ""}${runDiff.evidenceDelta} evidence item(s)`,
    `Tool discovery: ${toolDiscovery.summary.totalTools} tool(s), ${toolDiscovery.summary.versionMismatches} version mismatch, ${toolDiscovery.summary.missingTools} missing`,
    `Reviewer acceptance: ${reviewerAcceptance.summary.accepted} accepted, ${reviewerAcceptance.summary.requiredPending} required pending`,
    `Dependency impact: ${assetDependencyImpact.summary.affectedAssets} affected asset(s), ${assetDependencyImpact.summary.heldPublishes} held publish target(s), ${assetDependencyImpact.summary.pendingReceipts} pending receipt(s)`,
    `Final handoff: ${finalHandoffPacket.gate}, readyForPlatform=${String(finalHandoffPacket.readyForPlatform)}, ${finalHandoffPacket.packetHash}`,
    `Platform receipt: ${platformReceipt.state}, issued=${String(platformReceipt.issued)}, ${platformReceipt.checksum}`,
    `Review checklist: ${reviewItems.length > 0 ? reviewItems.join("; ") : "none"}`,
    `Module blockers: ${blockers.length > 0 ? blockers.join("; ") : "none"}`,
    "AI boundary: draft handoff text from module reports only; deterministic module gates remain authoritative.",
  ].join("\n");
}

function uniqueSorted<T extends string>(values: T[]): T[] {
  return Array.from(new Set(values)).sort((left, right) => left.localeCompare(right));
}

function stableTaskId(prefix: string, value: string): string {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${prefix}_${(hash >>> 0).toString(36)}`;
}

